"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[98063],{62416(e){e.exports=JSON.parse('{"tag":{"label":"sfs-turbo","permalink":"/docs-next/pr-preview/pr-445/docs/tags/sfs-turbo","allTagsPath":"/docs-next/pr-preview/pr-445/docs/tags","count":2,"items":[{"id":"blueprints/by-use-case/ai/litellm/litellm","title":"Build a Unified LLM Gateway with LiteLLM on CCE","description":"An LLM gateway acts as a centralized entry point for all interactions between applications and large language models. Rather than binding applications to specific model APIs or providers, the gateway introduces a stable interface that abstracts the underlying inference layer. This separation allows platform teams to control how requests are routed, which models are used, and where inference is executed, without requiring changes at the application level. In environments where multiple model backends coexist, such as locally hosted models on GPU infrastructure and external inference services, the gateway becomes the control plane for traffic management, policy enforcement, operational consistency and costs management.","permalink":"/docs-next/pr-preview/pr-445/docs/blueprints/by-use-case/ai/litellm/litellm"},{"id":"blueprints/by-use-case/ai/litellm/deploy-ollama-on-cce","title":"Deploy Ollama on CCE","description":"Ollama is a lightweight runtime for running large language models locally. It provides a simple way to download, manage, and serve models through a REST API, without requiring complex setup or deep knowledge of model serving frameworks. This makes it well suited for environments where ease of deployment and fast iteration are important.","permalink":"/docs-next/pr-preview/pr-445/docs/blueprints/by-use-case/ai/litellm/deploy-ollama-on-cce"}],"unlisted":false}}')}}]);